function balanceText(s){if(!s?.permissionGranted)return '使用状況は未取得です。アクセス許可後に更新してください。';const limit=s.entertainmentBudgetMinutes;return `今日の娯楽 ${s.entertainmentUsedMinutes}分 / ${limit===null?'制限なし':limit+'分'}、残り ${s.entertainmentRemainingMinutes===null?'制限なし':s.entertainmentRemainingMinutes+'分'}。学習 ${s.studyCompletedMinutes}分 / ${s.studyGoalMinutes||'未設定'}。`}
/** Real Usage + real Study snapshot decides locally; Usage and Study are never written here. */
function applyCoaching(){if(!S||!dailyBalance)return;const decision=coachingFromSnapshot(dailyBalance,S.settings.lifeBalance||{},now());if(decision.level==='NONE')return;if(S.settings.lifeBalance?.lastInterventionId===decision.interventionId)return;const text=coachingMessage(decision,decision.budget);if(!text)return;if(command('intervention',{interventionId:decision.interventionId,speaker:decision.speaker,reason:decision.reason,text})&&page==='chat')render()}
/** Notification tap: merge one intervention into the existing conversation, then open it. */
/** Finalized past days: merge authoritative local counts, then let the ledger keep CAS. */
window.platformDailyHistory=raw=>{try{const data=JSON.parse(raw)||{};if(!data.ok||!Array.isArray(data.days))return;const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;let skipped=0,saved=false;for(const day of pendingFinalizedDays(S.lifeBalanceAnalytics,data.days)){try{S=app.recordDailyAggregate({...day,...dailyCounts(S,day.date,zone)});saved=true}catch{skipped++}}if(saved&&page==='weekly')render();if(skipped)toast('一部の過去日は保存を見送りました。既存の記録は保持しています。')}catch{toast('過去日の集計を読み込めませんでした')}};
window.platformIntervention=raw=>{try{if(!S)return;const p=JSON.parse(raw)||{};if(!p.interventionId)return;const already=S.settings?.lifeBalance?.lastInterventionId===p.interventionId;if(!already){const text=interventionMessage(p.reason,p.speaker).body;if(!command('intervention',{interventionId:p.interventionId,speaker:p.speaker,reason:p.reason,text}))return}page='chat';render()}catch{toast('介入メッセージを開けませんでした')}};
/** Commitment tap: reuse the same conversation and insert the proposal at most once. */
window.platformCommitment=raw=>{try{if(!S)return;const p=JSON.parse(raw)||{};if(!p.commitmentId)return;page='chat';const activeId=S.initiative?.activeProposal?.commitmentId,recent=S.initiative?.lastRelatedId===p.commitmentId&&now()-(S.initiative?.lastPromptAt??0)<6*3600000;if(activeId!==p.commitmentId&&!recent){const proposal=evaluate(S,now(),{source:'notification'});if(proposal&&proposal.commitmentId===p.commitmentId&&validateProposal(proposal))command('initiativeShow',proposal,true)}render()}catch{toast('約束を開けませんでした')}};
/** Coaching first, then the analytics save in its own guard so analytics never suppresses coaching. */
window.platformDailyBalance=raw=>{try{dailyBalance=JSON.parse(raw);const el=document.querySelector('#daily-balance-summary');if(el)el.textContent=balanceText(dailyBalance);applyCoaching();try{const aggregate=aggregateFromSnapshot(dailyBalance,S.sessions);if(aggregate){S=app.recordDailyAggregate(aggregate);if(page==='weekly')render()}}catch{toast('集計の保存を見送りました。既存の記録は保持しています。')}}catch{dailyBalance=null}};
root.addEventListener('click',e=>{if(e.target.closest('[data-page="settings"],[data-action="refreshBalance"]'))host.requestDailyBalance?.();host.requestDailyHistory?.()});
function appCatalogRows(apps,categories){return apps.map(a=>`<label class="item">${a.icon?`<img width="48" height="48" alt="" src="${E(a.icon)}">`:''}<strong>${E(a.label)}</strong><small>${E(a.packageName)}</small><select data-app-category="${E(a.packageName)}">${[['ENTERTAINMENT','娯楽'],['STUDY','学習'],['NEUTRAL','対象外']].map(([v,l])=>`<option value="${v}" ${(categories[a.packageName]||'NEUTRAL')===v?'selected':''}>${l}</option>`).join('')}</select></label>`).join('')}
function showAppCatalog(){open(`<h2>アプリの使い方</h2><p>分類は端末内に保存します。使用状況の許可なしでも選択できます。</p><input id="app-search" placeholder="アプリ名・packageで検索" aria-label="アプリ検索"><div id="app-catalog-rows">${appCatalogRows(appCatalog.slice(0,40),S.settings.lifeBalance?.appCategories||{})}</div><p>最大40件ずつ表示します。検索で絞り込めます。</p><button data-action="cancel">閉じる</button>`)}
root.addEventListener('click',e=>{if(e.target.closest('[data-action="appCatalog"]')){open('<p>アプリを読み込んでいます。</p><button data-action="cancel">閉じる</button>');if(host.requestLaunchableApps)host.requestLaunchableApps();else toast('アプリ一覧はこの環境では利用できません')}});
window.platformLaunchableApps=raw=>{try{const data=JSON.parse(raw);if(!data.ok){toast('アプリ一覧を取得できませんでした');return}appCatalog=data.apps;if(dialog.open)showAppCatalog()}catch{toast('アプリ一覧を読み込めませんでした')}};
dialog.addEventListener('input',e=>{if(e.target.id==='app-search'){const q=e.target.value.toLocaleLowerCase();dialog.querySelector('#app-catalog-rows').innerHTML=appCatalogRows(appCatalog.filter(a=>(a.label+' '+a.packageName).toLocaleLowerCase().includes(q)).slice(0,40),S.settings.lifeBalance?.appCategories||{})}});
dialog.addEventListener('change',e=>{const pkg=e.target.dataset.appCategory;if(!pkg)return;const category=e.target.value;if(!['ENTERTAINMENT','STUDY','NEUTRAL'].includes(category))return;const lb=S.settings.lifeBalance||{};if(command('settings',{...S.settings,lifeBalance:{...lb,appCategories:{...lb.appCategories,[pkg]:category}}}))toast('分類を保存しました');else e.target.value=lb.appCategories?.[pkg]||'NEUTRAL'});
const latency=createLatencyTracker({enabled:Boolean(host?.debugToolsEnabled?.()),sink:line=>console.log(line)});
let latencyLocalTurn=false,pendingTyping=null,pendingRemote=null,finishProposal=null;
function typingLabel(speakers){const names=[...new Set((speakers||[]).filter(s=>['SAYO','NurseT'].includes(s)))],shown=names.map(s=>s==='NurseT'?'TTちゃん':'小夜');return shown.length>1?`${shown.join('と')}が話しています…`:`${shown[0]||'小夜'}が入力中…`}
function typingHtml(){if(!pendingTyping)return '';return `<article class="message-row incoming typing" role="status" aria-live="polite">${avatar(pendingTyping.speaker)}<div class="message incoming"><div class="message-speaker">${pendingTyping.name}</div><div class="bubble typing-bubble"><span class="typing-text">${E(pendingTyping.text)}</span><span class="typing-dots" aria-hidden="true"><span></span><span></span><span></span></span></div><button type="button" class="text-button typing-cancel" data-action="useLocalReply">端末内の返答を使う</button></div></article>`}
function showTyping(speakers){const names=[...new Set((speakers||[]).filter(s=>['SAYO','NurseT'].includes(s)))],first=names[0]||'SAYO';pendingTyping={speaker:first,name:first==='NurseT'?'TTちゃん':'小夜',text:typingLabel(names)};const end=document.querySelector('.messages #messages-end');if(end){end.insertAdjacentHTML('beforebegin',typingHtml());end.scrollIntoView({block:'end'})}}
function hideTyping(){pendingTyping=null;document.querySelector('.typing')?.remove()}
function initiativeChips(proposal,source){if(!proposal?.actionOptions?.length)return '';return `<div class="quick-actions initiative-actions" role="group" aria-label="次の一歩">${proposal.actionOptions.map((option,index)=>`<button type="button" class="${['start','more'].includes(option.id)?'primary':''}" data-initiative-action="${index}" data-initiative-source="${source}">${E(option.label)}</button>`).join('')}</div>`}
function maybePropose(){try{if(!S||active(S)||S.initiative?.activeProposal)return false;const proposal=evaluate(S,now(),{source:'open'});if(!proposal||!validateProposal(proposal))return false;if(!command('initiativeShow',proposal,true))return false;if(page==='chat')render();return true}catch{return false}}
function runInitiativeAction(index,source){try{const proposal=source==='finish'?finishProposal:S.initiative?.activeProposal,option=proposal?.actionOptions?.[index];if(!option)return;const clear=()=>{if(source==='finish')finishProposal=null};
 if(option.kind==='START_STUDY'){command('initiative',{event:'accepted',kind:proposal.kind,relatedId:proposal.relatedMaterialId},true);clear();const k=option.relatedTaskId?'tasks':option.relatedMaterialId?'materials':option.relatedGoalId?'goals':option.relatedPlanId?'plans':null,id=option.relatedTaskId||option.relatedMaterialId||option.relatedGoalId||option.relatedPlanId;start(k,id);return}
 if(option.kind==='SNOOZE'){if(proposal.commitmentId)command('commitmentAction',{commitmentId:proposal.commitmentId,op:'snooze',minutes:option.minutes||30},true);command('initiative',{event:'snoozed',minutes:option.minutes||30},true);clear();render();return}
 if(option.kind==='DECLINE'){if(proposal.commitmentId)command('commitmentAction',{commitmentId:proposal.commitmentId,op:'decline'},true);command('initiative',{event:'declined',kind:proposal.kind,quietToday:Boolean(option.quietToday)},true);clear();render();return}
 if(option.kind==='REVIEW'){command('initiative',{event:'accepted',kind:proposal.kind},true);clear();page='weekly';render();return}
 if(option.kind==='BREAK'){command('initiative',{event:'accepted',kind:proposal.kind},true);clear();render();action('break');return}
 }catch(error){toast(error.message)}}
function voiceToggle(){const v=voiceSettings(S.settings.voice),on=v.enabled;return `<button type="button" class="voice-toggle" data-action="toggleVoice" aria-pressed="${on}" aria-label="${on?'音声をオフにする':'音声をオンにする'}" title="${on?'音声 ON':'音声 OFF'}">${on?'🔊':'🔇'}</button>`}
let lastSpoken=0;
let app,remoteAI,S,page='chat',board='materials',finished=null,period='week',endDate,fromDate,filter={},recordsLimit=30,preview=null,timerHandle=null,chatLimit=100;
const labels={materials:'教材',goals:'目標',tasks:'タスク',plans:'今日の予定'};
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const now=()=>Date.now(),today=()=>dateKey(now(),S.settings.utcOffsetMinutes),title=(k,id)=>entity(S,k,id)?.title||'自由学習';
const fmt=t=>`${Math.floor(t/3600)}時間 ${Math.floor(t%3600/60)}分`,clock=t=>[Math.floor(t/3600),Math.floor(t%3600/60),Math.floor(t%60)].map(x=>String(x).padStart(2,'0')).join(':');
const timeOf=t=>new Date(t+S.settings.utcOffsetMinutes*60000).toISOString().slice(11,16);
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.style.display='none',6500)}
function speakMessages(messages,previous){try{const request=speechRequest(S,previous,now(),lastSpoken);if(!request)return;const v=voiceSettings(S.settings.voice),spoken=(messages??[]).filter(m=>m.speaker==='SAYO'?v.sayo:m.speaker==='NurseT'&&v.nurse),batch=speechQueue(spoken,8).map(m=>({speaker:m.speaker,text:m.text,volume:v.volume,priority:request.priority}));if(!batch.length)return;latency.mark('voice_request_at');latency.mark('voice_synthesis_started_at');if(host.speakBatch)host.speakBatch(JSON.stringify(batch));else if(host.speak)host.speak(JSON.stringify({...request,text:batch[0].text}));lastSpoken=now()}catch{}}
function prewarmVoice(){try{if(!S||!voiceSettings(S.settings.voice).enabled)return;latency.mark('voice_prewarm_started_at');host.prewarmVoice?.()}catch{}}
function command(a,p={},deferVoice=false){try{const previous=S?.reaction;if(a==='chat'){host.cancelVoice?.();remoteAI?.cancel()}S=app.command(a,p);if(a==='settings')host.cancelVoice?.();if(!deferVoice)speakMessages(app.lastVoiceMessages,previous);if(app.warning)toast(app.warning);return true}catch(e){S=app.state;toast(e.message);return false}}
let remoteTurn=0;
async function enhanceConversation(localMessages,userMessage,previous){
 const targets=(localMessages??[]).filter(m=>['SAYO','NurseT'].includes(m.speaker));
 if(!targets.length){speakMessages(localMessages,previous);return}
 const plan={order:targets.map(m=>m.speaker),allowedSpeakers:[...new Set(targets.map(m=>m.speaker))],maxMessages:Math.min(3,targets.length)};
 const turn=++remoteTurn;showTyping(plan.order);latency.mark('remote_request_started_at');
 const stage=setTimeout(()=>{if(pendingTyping){pendingTyping.text='接続先の起動を待っています。';const t=document.querySelector('.typing .typing-text');if(t)t.textContent=pendingTyping.text}},8000);
 try{
  const context=new ContextAssembler().assemble(S,now(),userMessage),result=await remoteAI.generate(remoteRequest(S,userMessage,targets[0].speaker,context,plan));
  if(turn!==remoteTurn||!S.settings.remoteAI)return;
  latency.mark('remote_first_response_at');latency.mark('remote_response_completed_at');
  const next=app.acceptRemoteTurn(targets.map(m=>m.id),result.messages??[{text:result.text,emotion:result.emotion}]);
  const byId=new Map(next.messages.map(m=>[m.id,m])),batch=localMessages.map(m=>byId.get(m.id)??m);
  hideTyping();render();latency.mark('assistant_text_rendered_at');speakMessages(batch,previous);
 }catch{
  const index=S.messages.findIndex(m=>m.id===targets[0].id),lastUser=S.messages.map(m=>m.speaker).lastIndexOf('user');
  if(turn===remoteTurn&&index>lastUser){hideTyping();toast('端末内の返答で続けます');latency.mark('assistant_text_rendered_at');speakMessages(localMessages,previous)}
 }finally{clearTimeout(stage);hideTyping();latency.flush()}
}
function avatar(who,small=false){const nurse=who==='NurseT',label=nurse?'ナースロボ＿タイプT':'小夜';return `<span class="avatar ${nurse?'avatar-nurse':'avatar-sayo'} ${small?'avatar-small':''}" role="img" aria-label="${label}"><img class="avatar-photo" src="avatar-sheet.png" alt=""></span>`}
function sayo(compact=false){if(S.settings.quiet)return '';const text=S.reaction?.text||'今日の一歩も、ここに残していこう。';return `<aside class="sayo"><div class="eyebrow">${S.reaction?.speaker==='NurseT'?'ナースロボ＿タイプＴ':'小夜 / SAYO'}</div><p>${E(text)}</p>${compact?'':'<button class="text-button" data-page="chat">会話の続きを開く</button>'}</aside>`}
function nav(){return `<nav class="nav" aria-label="メインナビゲーション">${[['chat','○','会話'],['home','⌂','今日'],['board','▤','学ぶこと'],['more','⋯','その他']].map(([k,icon,l])=>`<button data-page="${k}" class="${page===k?'current':''}" ${page===k?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${l}</button>`).join('')}</nav>`}
function render(){let content=page==='chat'?chat():page==='home'?home():page==='focus'?focus():page==='finish'?finish():page==='board'?collection():page==='records'?records():page==='memories'?memories():page==='journey'?journey():page==='settings'?settings():page==='weekly'?weeklyReview():more();root.innerHTML=`<main class="app"><header class="top"><span class="brand">新躍進政策</span>${page==='focus'?'<button class="text-button" data-page="home">今日へ</button>':active(S)?'<button class="small" data-page="focus">学習に戻る</button>':`<span class="date">${today().replaceAll('-',' / ')}</span>`}</header>${content}</main>${page==='focus'?'':nav()}`;tick();if(page==='chat')document.querySelector('#messages-end')?.scrollIntoView({block:'end'})}
function home(){const d=today(),r=report(S,now(),d,d),plan=S.plans.find(x=>x.date===d&&!x.done&&!x.archived);return `<div class="eyebrow">今日の続き</div>${sayo()}${previousCard()}${plan?`<section class="card"><div class="eyebrow">今日やること</div><h2 class="title">${E(plan.title)}</h2><button class="wide" data-study="plans" data-id="${plan.id}">この予定から始める</button></section>`:''}<button class="primary wide start" data-action="start">${active(S)?'学習に戻る':'勉強開始'}</button><p class="muted">予定なしでも、そのまま始められます。</p><div class="row wrap"><p class="muted">今日 ${Math.floor(r.seconds/60)}分 · ${r.sessions.length}回の学習</p><button class="text-button" data-page="records">振り返る</button></div><button class="wide" data-page="chat">小夜とTちゃんの会話へ</button>`}

function focus(){const x=active(S);if(!x){page='home';return home()}const k=x.segments.at(-1).kind;return `<section class="focus"><div class="eyebrow">${{study:'STUDY / 集中の時間',break:'BREAK / ひと休み',pause:'PAUSED / 一時停止'}[k]}</div><h1>${E(x.title)}</h1><div class="timer" id="timer">${clock(totals(x,now()).study)}</div><p class="muted">学習時間 <span id="break-total"></span></p><p class="break" id="break-left"></p><div class="actions">${k==='study'?'<button data-action="pause">一時停止</button><button data-action="break">休憩する</button>':'<button class="primary" data-action="resume">勉強を再開</button>'}</div><button class="${k==='study'?'primary':'ghost'} wide section" data-action="finish">終了して記録する</button><p class="muted">画面を閉じても計時は続きます。<br>手を止めるときは、一時停止か休憩を。</p>${sayo(true)}</section>`}
function finish(){const x=S.sessions.find(x=>x.sessionId===finished);if(!x){page='home';return home()}const seconds=totals(x,now()).study,d=today(),r=report(S,now(),d,d);const m=entity(S,'materials',x.relatedMaterialId);return `<div class="eyebrow">RECORDED / 今日の一歩</div><h1>ここまで、お疲れさま。</h1><section class="card"><div class="end-number">${fmt(seconds)}</div><p>${E(x.title)}</p><p class="muted">今日の累計 ${fmt(r.seconds)}<br>${Math.floor(seconds/60)}個の学びのしるしが残りました。</p>${sayo(true)}</section><section class="card"><div class="row"><h2>何を進めましたか？</h2><button class="small" data-classify="${x.sessionId}">内容を残す</button></div><p class="muted">${E(classLabel(x))}</p>${x.note?`<p class="note">${E(x.note)}</p>`:'<p class="muted">分類やメモは、あとからでも大丈夫。</p>'}${m?`<div class="item"><h3>${E(m.title)}</h3><progress class="progress" value="${m.progress}" max="${m.target}" aria-label="教材の進捗"></progress><p class="muted">${m.progress} / ${m.target} ${E(m.unit)}</p><div class="quick-actions" aria-label="教材の進捗を更新"><button data-progress-add="5" data-id="${m.id}">+5 ${E(m.unit)}</button><button data-progress-add="10" data-id="${m.id}">+10 ${E(m.unit)}</button><button data-progress="${m.id}">入力</button><button data-action="skipProgress">今は記録しない</button></div></div>`:''}${x.relatedTaskId&&!entity(S,'tasks',x.relatedTaskId)?.done?`<button class="ghost wide" data-done="tasks" data-id="${x.relatedTaskId}">このタスクを完了にする</button>`:''}</section>${initiativeChips(finishProposal,'finish')}<button class="primary wide section" data-page="chat">二人との会話へ</button><button class="text-button wide" data-page="records">今日の積み重ねを見る</button>`}
function classLabel(x){return Object.entries({relatedMaterialId:'materials',relatedGoalId:'goals',relatedTaskId:'tasks',relatedPlanId:'plans'}).filter(([f])=>x[f]).map(([f,k])=>title(k,x[f])).join(' / ')||'自由学習'}
function entityRow(k,o){const progress=['goals','materials'].includes(k),related=S.sessions.filter(x=>x[k==='materials'?'relatedMaterialId':k==='goals'?'relatedGoalId':k==='tasks'?'relatedTaskId':'relatedPlanId']===o.id),sec=related.reduce((n,x)=>n+totals(x,now()).study,0),first=related.length?Math.min(...related.map(x=>x.startTimestamp)):null;return `<article class="item"><div class="row"><div><h3 class="title">${E(o.title)}</h3><span class="muted">${progress?`${o.progress} / ${o.target} ${E(o.unit)}`:o.done?'完了':k==='plans'?E(o.date):'これから'}</span></div><button class="small" data-edit="${k}" data-id="${o.id}">編集</button></div>${progress?`<progress class="progress" value="${o.progress}" max="${o.target}" aria-label="${E(o.title)}の進捗"></progress>`:''}${o.memo?`<p class="note muted">${E(o.memo)}</p>`:''}<div class="actions">${!o.done&&!o.archived?`<button class="small" data-study="${k}" data-id="${o.id}">この続きから勉強</button>`:''}${!progress&&!o.done&&!o.archived?`<button class="small" data-done="${k}" data-id="${o.id}">完了にする</button>`:''}</div>${related.length?`<details class="history-detail"><summary>${fmt(sec)} · ${related.length}回の積み重ね</summary><p class="muted">${dateKey(first,S.settings.utcOffsetMinutes)}から取り組んでいます。</p>${progress?`<button class="text-button" data-history="${k}" data-id="${o.id}">この${labels[k]}の履歴を見る</button>`:''}</details>`:''}</article>`}
function collection(){let list=S[board].filter(x=>!x.archived),others=[];if(board==='plans'){others=list.filter(x=>x.date!==today());list=list.filter(x=>x.date===today())}return `<div class="eyebrow">LEARNING / 何を、どこまで</div><h1>次の一歩を、見つける。</h1><div class="tabs" role="navigation" aria-label="学習内容">${Object.entries(labels).map(([k,l])=>`<button data-board="${k}" class="${board===k?'current':''}">${l}</button>`).join('')}</div><section class="card"><div class="row"><h2>${labels[board]}</h2><button class="small primary" data-edit="${board}">＋ 追加</button></div>${list.length?list.map(x=>entityRow(board,x)).join(''):'<p class="empty">まだ登録はありません。<br>取り組みたいことを、一つから。</p>'}</section>${others.length?`<details class="section"><summary>ほかの日の予定</summary>${others.sort((a,b)=>a.date.localeCompare(b.date)).map(x=>entityRow(board,x)).join('')}</details>`:''}<details class="section"><summary>アーカイブ（記録は保持）</summary>${S[board].filter(x=>x.archived).map(x=>entityRow(board,x)).join('')||'<p class="muted">アーカイブはありません。</p>'}</details>`}
function range(){endDate??=today();if(period==='day')return [endDate,endDate];if(period==='week')return [shiftDate(endDate,-6),endDate];if(period==='month')return [endDate.slice(0,8)+'01',endDate];if(period==='all'){const oldest=S.sessions.length?Math.min(...S.sessions.map(x=>x.startTimestamp)):now();return [dateKey(oldest,S.settings.utcOffsetMinutes),today()]}return [fromDate??shiftDate(endDate,-30),endDate]}
function records(){const [start,end]=range(),r=report(S,now(),start,end,filter),previous=period==='day'?report(S,now(),shiftDate(start,-1),shiftDate(start,-1),filter):null,best=Object.entries(r.materials).sort((a,b)=>b[1]-a[1])[0];let bars=r.daily;const monthly=Object.keys(bars).length>31;if(monthly){bars={};for(const [d,v] of Object.entries(r.daily))bars[d.slice(0,7)]=(bars[d.slice(0,7)]||0)+v}const max=Math.max(60,...Object.values(bars));const sessions=S.sessions.filter(x=>(r.sessions.includes(x.sessionId)||dateKey(x.startTimestamp,S.settings.utcOffsetMinutes)>=start&&dateKey(x.startTimestamp,S.settings.utcOffsetMinutes)<=end)&&(!filter.material||x.relatedMaterialId===filter.material)&&(!filter.goal||x.relatedGoalId===filter.goal)).slice().reverse();return `<div class="eyebrow">REVIEW / 積み重ねを見る</div><h1>歩いてきた道のり。</h1><div class="tabs">${[['day','1日'],['week','7日'],['month','今月'],['all','全期間'],['custom','期間指定']].map(([k,l])=>`<button data-period="${k}" class="${period===k?'current':''}">${l}</button>`).join('')}</div><div class="row wrap"><p class="muted">${start} 〜 ${end}</p><button class="text-button" data-action="range">日付・教材・目標を選ぶ</button></div>${filter.material||filter.goal?`<p class="pill">${E(filter.material?title('materials',filter.material):title('goals',filter.goal))}</p>`:''}<div class="stats"><section class="card stat"><p class="muted">学習した時間</p><strong>${fmt(r.seconds)}</strong><p class="muted">${previous?`前日比 ${r.seconds-previous.seconds>=0?'+':''}${Math.floor((r.seconds-previous.seconds)/60)}分`:`${r.sessions.length}回の学習`}</p></section><section class="card stat"><p class="muted">学習した日</p><strong>${r.studyDays}日</strong><p class="muted">完了タスク ${r.completedTasks.length}件</p></section></div><section class="card"><h2>${monthly?'月ごと':'日ごと'}の積み重ね</h2><div class="bars">${Object.entries(bars).map(([d,v])=>`<div class="bar"><span>${monthly?d:d.slice(5)}</span><progress value="${v}" max="${max}" aria-label="${d} ${Math.floor(v/60)}分"></progress><span>${Math.floor(v/60)}分</span></div>`).join('')}</div></section><section class="card"><h2>取り組んだこと</h2>${best?`<p class="muted">いちばん向き合った教材</p><h3>${E(title('materials',best[0]))}</h3><p class="muted">${fmt(best[1])}</p>`:'<p class="muted">この期間の学習は、まだありません。</p>'}${r.materialProgress.concat(r.goalProgress).slice(-12).map(e=>`<p class="note">${E(e.title)}：${e.before} → ${e.after}</p>`).join('')}${r.completedTasks.slice(-12).map(x=>`<p class="note">✓ ${E(x.title)}</p>`).join('')}</section><section class="card"><h2>学習の記録</h2>${sessions.slice(0,recordsLimit).map(x=>`<article class="item"><div class="muted">${dateKey(x.startTimestamp,S.settings.utcOffsetMinutes)} · ${timeOf(x.startTimestamp)}${x.endTimestamp!==null?'〜'+timeOf(x.endTimestamp):'〜学習中'}</div><div class="row section"><div><h3 class="title">${E(x.title)}</h3><span class="muted">${fmt(totals(x,now()).study)} · 休憩 ${Math.floor(totals(x,now()).break/60)}分</span></div><button class="small" data-classify="${x.sessionId}">内容</button></div><p class="muted">${E(classLabel(x))}</p>${x.note?`<p class="note">${E(x.note)}</p>`:''}</article>`).join('')||'<p class="empty">記録はこれから少しずつ。</p>'}${sessions.length>recordsLimit?'<button class="wide" data-action="moreRecords">続きを見る</button>':''}</section>`}
function journey(){const m=metrics(S,now());return `<div class="eyebrow">OUR JOURNEY</div><h1>一緒に重ねた時間。</h1><p class="muted">途切れた日があっても、それまでの努力は消えません。</p><section class="card"><span class="muted">学びのしるし</span><div class="metric">${m.reward}<small>個</small></div><p class="muted">終えた学習の1分が、一つのしるしになります。</p></section><div class="stats"><section class="card stat"><p class="muted">一緒に勉強した時間</p><strong>${m.studyBond}時間</strong><p class="muted">Study Bond</p></section><section class="card stat"><p class="muted">顔を合わせた日</p><strong>${m.familiarity}日</strong><p class="muted">Familiarity</p></section></div><section class="card"><h2>${m.sharedMemories}件の思い出</h2><p class="muted">教材の進歩や目標達成を、言葉でも振り返れます。</p><button class="wide" data-page="memories">思い出を開く</button></section>${sayo()}`}
function memories(){return `<div class="eyebrow">MEMORIES</div><div class="row wrap"><h1>覚えておきたいこと。</h1><button class="small" data-action="memory">＋ 残す</button></div><section class="card">${S.memories.slice().reverse().map(m=>`<article class="memory"><div class="muted">${dateKey(m.timestamp,S.settings.utcOffsetMinutes)} · ${m.category==='manual'?'あなたの言葉':'学習の節目'}</div><p class="note">${E(m.text)}</p></article>`).join('')||'<p class="empty">はじめての勉強や教材の進歩が、ここに残ります。</p>'}</section>`}
function more(){return `<div class="eyebrow">YOUR SPACE</div><h1>いつもの場所を整える。</h1><div class="menu-grid section"><button data-page="weekly">生活バランスの週次記録<span class="info">記録のある日と先週比</span></button><button data-page="records">振り返り<span class="info">今日と一週間の学習</span></button><button data-page="journey">一緒に積み重ねたこと<span class="info">学びのしるし・二人との時間</span></button><button data-page="memories">思い出<span class="info">覚えておきたい学習の節目</span></button><button data-page="settings">設定・バックアップ<span class="info">過ごし方と、大切な記録の保管</span></button>${host.debugToolsEnabled?.()?'<button data-action="debugLifeBalance">（開発）LifeBalanceWorkerを今すぐ実行<span class="info">debug build only</span></button>':''}${host.migrationQaEnabled?.()?'<button data-action="migrationQa">（移行QA）バックアップを読み取り専用で検証<span class="info">migration QA build only</span></button>':''}</div>`}
function settings(){const remoteReady=remoteAI?.available(),endpoint=host.remoteAIEndpoint?.()||'',lb=S.settings.lifeBalance||{},cats=lb.appCategories||{},companion=S.settings.companion||{proactivity:'NORMAL',quietDay:null};return `<div class="eyebrow">SETTINGS</div><h1>自分に合うかたちで。</h1><section class="card"><h2>過ごし方</h2><form data-form="settings"><label>呼び名<input name="name" maxlength="80" value="${E(S.settings.name)}"></label><label>いつもの休憩（分）<input name="breakMinutes" type="number" required min="1" max="180" value="${S.settings.breakMinutes}"></label><label>記録の時差（UTCからの分。日本は540）<input name="utcOffsetMinutes" type="number" min="-720" max="840" required step="1" value="${S.settings.utcOffsetMinutes}"></label><p class="muted">時差を変えると、過去の学習の日別配分も変わります。</p><label class="check"><input name="quiet" type="checkbox" ${S.settings.quiet?'checked':''}>小夜の言葉を控える</label><label class="check"><input name="notifications" type="checkbox" ${S.settings.notifications?'checked':''}>休憩終了を通知する</label><label>Remote AI Backend URL<input name="remoteAIEndpoint" type="url" inputmode="url" maxlength="2048" placeholder="https://…/v1/reactions" value="${E(endpoint)}"></label><label class="check"><input name="remoteAI" type="checkbox" ${S.settings.remoteAI?'checked':''}>会話の拡張を使う</label><p class="muted">会話の拡張：${remoteReady?'利用可能':'未設定（端末内ルールで会話します）'}。URLは公開接続先で、秘密情報ではありません。有効時のみ、選択された会話・学習文脈をBackendへ送ります。APIキーは端末へ保存しません。</p><button type="submit" class="primary wide">設定を保存</button></form><button class="text-button" data-action="permission">通知を許可する</button><p class="muted">端末の通知許可：${host.notificationAllowed()?'許可':'未許可'}。許可しなくても勉強できます。省電力設定により通知が遅れる場合があります。</p></section><section class="card life-balance"><h2>生活バランス</h2><p id="daily-balance-summary">現在の集計は更新ボタンで確認できます。</p><button type="button" data-action="refreshBalance">今日の状況を更新</button><button type="button" data-action="appCatalog">起動可能アプリを選ぶ</button><p class="muted">使用状況へのアクセス: ${host.usageAccessAllowed?.()===true?'許可済み':'未許可'}。未許可でも学習と会話は通常どおり使えます。</p><button type="button" data-action="usageAccess">Android設定を開く</button><form data-form="lifeBalance"><label>1日の学習目標（分、0は未設定）<input name="studyGoalMinutes" type="number" required min="0" max="1440" value="${Number(lb.studyGoalMinutes||0)}"></label><label>今日のモード<select name="dailyMode">${[['NORMAL','通常日'],['HOLIDAY','休日'],['FOCUS','集中日'],['UNLIMITED','制限なし']].map(([v,l])=>`<option value="${v}" ${lb.dailyMode===v?'selected':''}>${l}</option>`).join('')}</select></label><div class="two">${[['NORMAL','通常日'],['HOLIDAY','休日'],['FOCUS','集中日']].map(([v,l])=>`<label>${l}の娯楽分<input name="budget_${v}" type="number" min="0" max="1440" value="${Number(lb.budgetMinutes?.[v]??(v==='NORMAL'?90:v==='HOLIDAY'?180:60))}"></label>`).join('')}</div><label>介入強度<select name="interventionLevel">${[['GENTLE','やさしい'],['NORMAL','普通'],['STRICT','厳しめ']].map(([v,l])=>`<option value="${v}" ${lb.interventionLevel===v?'selected':''}>${l}</option>`).join('')}</select></label><label>通知の間隔（分）<input name="cooldownMinutes" type="number" min="15" max="1440" value="${Number(lb.cooldownMinutes??120)}"></label><label class="check"><input name="usageInConversation" type="checkbox" ${lb.usageInConversation!==false?'checked':''}>要約したUsage情報を会話に使う</label><label class="check"><input name="usageNotifications" type="checkbox" ${lb.usageNotifications!==false?'checked':''}>長時間利用時に声をかける</label><label>娯楽アプリ分類（1行1件: package=CATEGORY）<textarea name="appCategories" maxlength="4000" placeholder="com.google.android.youtube=ENTERTAINMENT\ncom.android.chrome=STUDY">${E(Object.entries(cats).map(([p,c])=>`${p}=${c}`).join('\n'))}</textarea></label><p class="muted">例: YouTube + X を娯楽、Chrome + ChatGPT を学習として合計集計できます。</p><button type="submit" class="primary wide">生活バランスを保存</button></form></section><section class="card companion"><h2>二人との距離感</h2><form data-form="companion"><label>声のかけ方<select name="proactivity">${[['LOW','控えめ'],['NORMAL','標準'],['HIGH','多め']].map(([v,l])=>`<option value="${v}" ${companion.proactivity===v?'selected':''}>${l}</option>`).join('')}</select></label><button type="submit" class="primary wide">保存</button></form><button type="button" data-action="quietToday">今日は静かに</button><p class="muted">${companion.quietDay===today()?'今日は静かに設定中です。会話はそのまま使えます。':'「今日は静かに」を押すと、この端末の今日の日付の間は二人からの提案を控えます。'}</p><p class="muted">提案は、断っても責めません。断ったあとはしばらく間をあけます。</p></section>${voiceForm()}<section class="card"><h2>大切な記録を守る</h2><p class="muted">学習・進捗・思い出を一つのファイルへ。端末を替える前にも書き出してください。</p><div class="actions"><button data-action="export">書き出す</button><button data-action="import">復元する</button></div><p class="muted">復元する前の記録と読み込んだ原本は、アプリ内にも退避します。</p></section><section class="card"><h2>新躍進政策 0.8</h2><p class="muted">Usageの生データは端末外へ送らず、会話には必要最小限の要約だけを使います。</p></section>`}
function open(html){dialog.innerHTML=html;dialog.showModal()}
function actions(label='保存'){return `<p class="error" role="alert" id="form-error"></p><div class="actions"><button type="submit" class="primary">${label}</button><button type="button" data-action="cancel">閉じる</button></div>`}
function options(k,v){return `<option value="">指定なし</option>${S[k].filter(x=>!x.archived||x.id===v).map(x=>`<option value="${x.id}" ${v===x.id?'selected':''}>${E(x.title)}</option>`).join('')}`}
function relations(o={},full=true){return `<label>教材<select name="relatedMaterialId">${options('materials',o.relatedMaterialId)}</select></label><label>目標<select name="relatedGoalId">${options('goals',o.relatedGoalId)}</select></label><label>タスク<select name="relatedTaskId">${options('tasks',o.relatedTaskId)}</select></label>${full?`<label>今日の予定<select name="relatedPlanId">${options('plans',o.relatedPlanId)}</select></label>`:''}`}
function edit(k,id){const o=entity(S,k,id)||{},progress=['materials','goals'].includes(k);open(`<h2>${labels[k]}を${id?'編集':'追加'}</h2><form data-form="entity" data-kind="${k}" data-id="${id||''}"><label>名前<input name="title" maxlength="200" required autofocus value="${E(o.title)}"></label>${progress?`<div class="two"><label>現在<input name="progress" type="number" min="0" step="any" required value="${o.progress??0}"></label><label>目標<input name="target" type="number" min="1" step="any" required value="${o.target??100}"></label></div><label>単位（ページ・問・章など）<input name="unit" maxlength="30" value="${E(o.unit??(k==='materials'?'ページ':'%'))}"></label>`:`${k==='plans'?`<label>日付<input name="date" type="date" required value="${o.date??today()}"></label>`:''}<details><summary>教材・目標と関連づける</summary>${relations(o,false)}</details><label class="check"><input name="done" type="checkbox" ${o.done?'checked':''}>完了</label>`}<label>メモ<textarea name="memo" maxlength="2000">${E(o.memo)}</textarea></label>${id?`<label class="check"><input name="archived" type="checkbox" ${o.archived?'checked':''}>アーカイブ（記録は保持）</label>`:''}${actions()}</form>`)}
function classify(id){const x=S.sessions.find(x=>x.sessionId===id);open(`<h2>何を進めましたか？</h2><form data-form="classify" data-id="${id}"><label>学習内容<input name="title" value="${E(x.title)}" maxlength="200"></label><label>教材<select name="relatedMaterialId">${options('materials',x.relatedMaterialId)}</select></label><details><summary>目標・タスク・予定</summary><label>目標<select name="relatedGoalId">${options('goals',x.relatedGoalId)}</select></label><label>タスク<select name="relatedTaskId">${options('tasks',x.relatedTaskId)}</select></label><label>予定<select name="relatedPlanId">${options('plans',x.relatedPlanId)}</select></label></details><label>できたこと・次に進めたいこと<textarea name="note" maxlength="2000">${E(x.note)}</textarea></label>${actions('内容を保存')}</form>`)}
function start(k,id){if(active(S)){page='focus';render();return}const payload={sessionId:crypto.randomUUID(),title:k?title(k,id):'自由学習'};if(k)payload[{materials:'relatedMaterialId',goals:'relatedGoalId',tasks:'relatedTaskId',plans:'relatedPlanId'}[k]]=id;if(command('start',payload)){page='focus';render()}}
function action(a){const x=active(S);if(a==='usageAccess'){host.openUsageAccessSettings?.();return}if(a==='migrationQa'){host.importMigrationSource?.();return}if(a==='debugLifeBalance'){try{const r=JSON.parse(host.runLifeBalanceNow?.()||'{}');toast(`LifeBalance: ${r.checked?`reason=${r.reason} speaker=${r.speaker??'none'} notified=${r.notified}`:`no-op reason=${r.reason}`}`)}catch{toast('LifeBalanceを実行できませんでした')}return}if(a==='licenses'){open(`<h2>クレジット・利用条件</h2><pre class="license-text">${E(host.licenses?host.licenses():'利用条件ファイルは未準備です。')}</pre><button type="button" data-action="cancel">閉じる</button>`);return}if(a==='start')return start();if(a==='olderMessages'){chatLimit+=100;render()}else if(a==='skipProgress'){page='home';render()}else if(a==='interact'){command('interact');render()}else if(a==='pause'||a==='resume'){if(command(a,{sessionId:x.sessionId}))render()}else if(a==='finish'){if(command('finish',{sessionId:x.sessionId})){finished=x.sessionId;finishProposal=followUp(S,now());page='finish';render()}else finishProposal=null}else if(a==='break'){open(`<h2>ひと息、つこう。</h2><form data-form="break"><label>休憩（分）<input name="minutes" type="number" required min="1" max="180" value="${S.settings.breakMinutes}"></label><div class="actions">${[5,10,30].map(n=>`<button type="button" data-minutes="${n}">${n}分</button>`).join('')}</div><p class="muted">休憩は学習時間に加算しません。再開は自分のタイミングで。</p>${actions('休憩を始める')}</form>`)}else if(a==='memory'){open(`<h2>覚えておきたいこと</h2><form data-form="memory"><label>思い出<textarea name="text" maxlength="2000" required autofocus></textarea></label>${actions('残す')}</form>`)}else if(a==='range'){const [start,end]=range();open(`<h2>振り返る範囲を選ぶ</h2><form data-form="range"><div class="two"><label>開始日<input name="start" type="date" required value="${start}"></label><label>終了日<input name="end" type="date" required value="${end}"></label></div><label>教材<select name="material">${options('materials',filter.material)}</select></label><label>目標<select name="goal">${options('goals',filter.goal)}</select></label>${actions('表示する')}</form>`)}else if(a==='moreRecords'){recordsLimit+=30;render()}else if(a==='export')host.exportData();else if(a==='import'){if(x){toast('学習を終了してから復元してください');return}host.importData()}else if(a==='quietToday'){if(command('companion',{quietDay:today()})){toast('今日は静かにします。会話はそのまま使えます。');render()}}else if(a==='permission'){if(command('settings',{...S.settings,notifications:true})){host.enableNotifications();render()}}}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.initiativeAction!==undefined){runInitiativeAction(Number(b.dataset.initiativeAction),b.dataset.initiativeSource||'active');return}if(b.dataset.action==='useLocalReply'){remoteAI?.cancel();return}if(b.dataset.action==='toggleVoice'){const v=voiceSettings(S.settings.voice);if(command('settings',{...S.settings,voice:{...v,enabled:!v.enabled}})){if(v.enabled)host.cancelVoice?.();render()}return}if(b.dataset.page){page=b.dataset.page;if(page==='records')command('review',{weekly:period==='week'});render()}else if(b.dataset.board||b.dataset.openBoard){board=b.dataset.board||b.dataset.openBoard;page='board';render()}else if(b.dataset.replay){const m=S.messages?.find(x=>x.id===b.dataset.replay),v=voiceSettings(S.settings.voice);if(m&&v.enabled&&!S.settings.quiet&&!inQuietHours(v,now(),S.settings.utcOffsetMinutes)&&(m.speaker==='SAYO'?v.sayo:v.nurse)){host.speak?.(JSON.stringify({speaker:m.speaker,text:m.text,volume:v.volume,priority:2}));toast('音声を準備しています。')}else toast('音声設定をONにしてください。')}else if(b.dataset.progressAdd){const m=entity(S,'materials',b.dataset.id),progress=Math.min(m.target,m.progress+Number(b.dataset.progressAdd));if(command('saveEntity',{...m,kind:'materials',progress}))render()}else if(b.dataset.progress){const m=entity(S,'materials',b.dataset.progress);open(`<h2>今日はどこまで進みましたか？</h2><p>${E(m.title)} · 現在 ${m.progress} ${E(m.unit)}</p><form data-form="progress"><input type="hidden" name="id" value="${m.id}"><label>進んだところ（${E(m.unit)}）<input type="number" name="progress" min="0" max="${m.target}" step="any" value="${m.progress}" required autofocus></label>${actions('進捗を残す')}</form>`)}else if(b.dataset.edit)edit(b.dataset.edit,b.dataset.id);else if(b.dataset.study)start(b.dataset.study,b.dataset.id);else if(b.dataset.done){const k=b.dataset.done,o=entity(S,k,b.dataset.id);if(command('saveEntity',{...o,kind:k,done:true}))render()}else if(b.dataset.classify)classify(b.dataset.classify);else if(b.dataset.period){period=b.dataset.period;if(period==='custom')action('range');else{recordsLimit=30;render()}}else if(b.dataset.history){const k=b.dataset.history;if(k==='materials')filter={material:b.dataset.id};else if(k==='goals')filter={goal:b.dataset.id};else filter={};period='all';page='records';render()}else action(b.dataset.action)});
dialog.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.conversationChoice){if(command('conversation',{text:b.dataset.conversationChoice,selection:{kind:b.dataset.kind,id:b.dataset.id}})){dialog.close();render()}return}if(b?.dataset.action==='cancel')dialog.close();if(b?.dataset.minutes)dialog.querySelector('[name=minutes]').value=b.dataset.minutes});
function submit(e){e.preventDefault();const f=e.target,p=Object.fromEntries(new FormData(f)),type=f.dataset.form;const button=f.querySelector('[type=submit]');button.disabled=true;let ok=false;try{
 if(type==='conversation'){hideTyping();pendingRemote=null;latency.reset();latency.mark('user_submit_at');const previous=S?.reaction,useRemote=Boolean(S.settings.remoteAI&&remoteAI?.available());ok=command('chat',p,useRemote);if(ok){latency.mark('reply_plan_created_at');latencyLocalTurn=!useRemote;const localMessages=structuredClone(app.lastVoiceMessages??[]);if(useRemote)pendingRemote={localMessages,text:p.text,previous};const r=app.lastConversationResult;if(r?.route==='focus')page='focus';else if(r?.route==='records'){page='records';period=r.payload.weekly?'week':'day'}else if(r?.route==='break'){render();action('break');return}else if(r?.route==='progress'){const m=entity(S,'materials',r.materialId);edit('materials',m.id);return}else if(r?.choices?.length>1){open(`<h2>どの学習ですか？</h2>${r.choices.map(c=>`<button class="wide" data-conversation-choice="${E(c.item.title)}" data-kind="${c.kind}" data-id="${E(c.item.id)}">${E(c.item.title)} · ${labels[c.kind]}</button>`).join('')}<button data-action="cancel">閉じる</button>`);return}}}
 else if(type==='entity'){for(const k of ['progress','target'])if(k in p)p[k]=Number(p[k]);for(const k of ['done','archived'])p[k]=p[k]==='on';ok=command('saveEntity',{...p,kind:f.dataset.kind,id:f.dataset.id||undefined})}
 else if(type==='classify'){if(p.title==='自由学習'&&p.relatedMaterialId)p.title=title('materials',p.relatedMaterialId);ok=command('classify',{...p,sessionId:f.dataset.id})}
 else if(type==='break')ok=command('break',{sessionId:active(S).sessionId,minutes:Number(p.minutes)});
 else if(type==='memory')ok=command('memory',p);
 else if(type==='progress'){const m=entity(S,'materials',p.id);ok=command('saveEntity',{...m,kind:'materials',progress:Number(p.progress)})}
 else if(type==='companion'){ok=command('companion',{proactivity:String(p.proactivity||'NORMAL')});if(ok)toast('二人との距離感を保存しました')}
 else if(type==='voice'){for(const k of ['enabled','sayo','nurse','quietHours'])p[k]=p[k]==='on';for(const k of ['volume','quietStart','quietEnd'])p[k]=Number(p[k]);ok=command('settings',{...S.settings,voice:voiceSettings(p)});host.cancelVoice?.();if(ok)toast('音声設定を保存しました')}
 else if(type==='settings'){for(const k of ['breakMinutes','utcOffsetMinutes'])p[k]=Number(p[k]);for(const k of ['quiet','notifications','remoteAI'])p[k]=p[k]==='on';const endpoint=p.remoteAIEndpoint;delete p.remoteAIEndpoint;if(host.setRemoteAIEndpoint&&!host.setRemoteAIEndpoint(endpoint))throw Error('Backend URLはhttps://で始まる完全なURLを入力してください');ok=command('settings',p);if(ok)toast('設定を保存しました')}
 else if(type==='lifeBalance'){const categories={};for(const line of String(p.appCategories||'').split(/\n+/)){const [pkg,cat]=line.split('=').map(x=>x.trim());if(pkg&&['ENTERTAINMENT','STUDY','NEUTRAL'].includes(cat))categories[pkg]=cat}const old=S.settings.lifeBalance||{};const lifeBalance={...old,dailyMode:p.dailyMode,modeDay:new Date().toLocaleDateString('sv-SE'),studyGoalMinutes:Number(p.studyGoalMinutes),budgetMinutes:{NORMAL:Number(p.budget_NORMAL),HOLIDAY:Number(p.budget_HOLIDAY),FOCUS:Number(p.budget_FOCUS)},interventionLevel:p.interventionLevel,cooldownMinutes:Number(p.cooldownMinutes),usageInConversation:p.usageInConversation==='on',usageNotifications:p.usageNotifications==='on',appCategories:categories};ok=command('settings',{...S.settings,lifeBalance});if(ok)toast('生活バランスを保存しました')}
 else if(type==='range'){if(dateMs(p.start)>dateMs(p.end))throw Error('開始日を終了日以前にしてください');fromDate=p.start;endDate=p.end;filter={material:p.material,goal:p.goal};period='custom';recordsLimit=30;ok=true}
 else if(type==='restore'){S=app.restore(preview);preview=null;page='home';finished=null;ok=true;toast('記録を復元しました')}
 if(ok){if(dialog.open)dialog.close();render();if(type==='conversation'){latency.mark('user_bubble_rendered_at');if(pendingRemote){const job=pendingRemote;pendingRemote=null;enhanceConversation(job.localMessages,job.text,job.previous)}else if(latencyLocalTurn){latency.mark('assistant_text_rendered_at');latency.flush()}latencyLocalTurn=false}}else{const error=f.querySelector('#form-error');if(error)error.textContent='保存できませんでした。通知内容を確認してください。'}
 }catch(error){const el=f.querySelector('#form-error');if(el)el.textContent=error.message;else toast(error.message)}finally{button.disabled=false}}
dialog.addEventListener('submit',submit);root.addEventListener('submit',submit);
window.platformMessage=text=>toast(text);
window.platformVoiceEvent=(name,at)=>{try{const time=Number(at)||now();if(name==='prewarm_completed')latency.markOnce('voice_prewarm_completed_at',time);else if(name==='synthesis_ready')latency.markOnce('voice_first_chunk_ready_at',time);else if(name==='playback_started'){latency.markOnce('voice_playback_started_at',time);latency.flush()}else if(name==='playback_completed')latency.markOnce('voice_playback_completed_at',time);}catch{}};
window.platformImportCandidate=raw=>{try{preview=app.previewImport(raw);open(`<h2>この記録を復元しますか？</h2><p class="notice">現在の記録を置き換えます。今の記録は復元直前に退避します。</p><p>学習 ${preview.sessions}件 · 教材 ${preview.materials}件<br>思い出 ${preview.memories}件 · ${fmt(preview.metrics.seconds)}</p><p class="muted">保存形式 ${preview.fromVersion} → 2<br>学習ID・学習時間を保持します。</p><form data-form="restore"><label class="check"><input type="checkbox" required>この内容で置き換える</label>${actions('復元する')}</form>`)}catch(error){toast('復元できません：'+error.message)}};
/** Migration rehearsal only: verify a backup read-only, then show PASS/FAIL. Never restores. */
window.platformMigrationQaSource=(raw,meta)=>{let report;try{report=assessMigration(raw,meta?JSON.parse(meta):{})}catch(error){report={pass:false,warnings:[],failures:['移行リハーサルを実行できません：'+error.message],fileName:null,sourceFormat:null,sourceSchemaVersion:null,targetSchemaVersion:2,sourceSha256:null,entityCounts:null,metrics:null,lifeBalance:null,weeklyAggregates:null}}open(migrationReportHtml(report))};
window.platformResume=()=>{if(!app)return;try{S=app.load();if(!dialog.open)render();scheduleTick();host.requestDailyBalance?.();host.requestDailyHistory?.();prewarmVoice();maybePropose()}catch(error){toast(error.message)}};
window.platformBack=()=>{if(dialog.open){dialog.close();return true}if(page!=='home'){page='home';render();return true}return false};
function tick(){if(!S||document.hidden)return;const x=active(S);if(!x)return;const t=document.querySelector('#timer');if(t)t.textContent=clock(totals(x,now()).study);const bt=document.querySelector('#break-total');if(bt)bt.textContent=` · 休憩 ${Math.floor(totals(x,now()).break/60)}分`;const bl=document.querySelector('#break-left');if(bl&&x.breakUntil)bl.textContent=x.breakUntil>now()?`休憩 あと ${clock((x.breakUntil-now())/1000)}`:'休憩の時間になりました。準備ができたら再開しましょう。'}
function scheduleTick(){clearInterval(timerHandle);timerHandle=null;if(!document.hidden)timerHandle=setInterval(tick,1000)}
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInterval(timerHandle);timerHandle=null}else window.platformResume()});
try{if(!host)throw Error('Androidアプリ内で開いてください。PCサーバーへの接続は必要ありません。');app=new StudyApplication(host);remoteAI=new RemoteAIProvider(host);S=app.load();command('visit');if(active(S))page='focus';render();scheduleTick();host.requestDailyBalance?.();host.requestDailyHistory?.();prewarmVoice();maybePropose();if(app.warning)toast(app.warning)}catch(error){root.innerHTML=`<main class="app"><h1>記録を開けませんでした</h1><p class="notice">${E(error.message)}</p><p class="muted">元データを保護するため、空の記録への置き換えは行いません。</p></main>`}

function previousCard(){const p=continuation(S,now());if(!p)return '';const related=S.sessions.filter(x=>x.endTimestamp!==null&&x[p.kind==='tasks'?'relatedTaskId':p.kind==='goals'?'relatedGoalId':p.kind==='plans'?'relatedPlanId':'relatedMaterialId']===p.item.id).sort((a,b)=>b.endTimestamp-a.endTimestamp)[0];const task=p.kind==='tasks'?p.item:null,m=p.kind==='materials'?p.item:entity(S,'materials',p.item.relatedMaterialId);return `<section class="card continuation"><div class="eyebrow">${related?'前回の続き':'話していた学習'}</div><h2 class="title">${E(m?.title||p.item.title)}</h2>${task?`<p class="note">${E(task.title)}</p>`:''}<p class="muted">${related?dateKey(related.endTimestamp,S.settings.utcOffsetMinutes)+' '+timeOf(related.endTimestamp)+'に学習':'次に取り組むこと'}${m?` · ${m.progress} / ${m.target} ${E(m.unit)}`:''}</p><button class="primary wide" data-study="${p.kind}" data-id="${p.item.id}">続きを勉強</button><div class="quick-actions"><button data-open-board="materials">別の教材</button><button data-action="start">自由学習</button></div></section>`}
function conversationForm(){return `<section class="conversation section"><form data-form="conversation"><label for="conversation-input">ひとこと、ここから<input id="conversation-input" name="text" maxlength="300" autocomplete="off" placeholder="続きやる・教材名・振り返り" required></label><button type="submit" class="wide">伝える</button></form><details><summary>最近のやりとり</summary>${(S.conversation?.turns??[]).map(t=>`<p class="note"><strong>${t.speaker==='user'?'あなた':t.speaker==='SAYO'?'小夜':'ナースロボ＿タイプＴ'}</strong><br>${E(t.text)}</p>`).join('')||'<p class="muted">ここで話した学習の続きが残ります。</p>'}</details></section>`}

function voiceForm(){const v=voiceSettings(S.settings.voice);return `<section class="card"><h2>声の過ごし方</h2><form data-form="voice">${[['enabled','音声を使う'],['sayo','小夜/SAYO'],['nurse','ナースロボ＿タイプＴ'],['quietHours','静かな時間は音声を休む']].map(([k,l])=>`<label class="check"><input type="checkbox" name="${k}" ${v[k]?'checked':''}>${l}</label>`).join('')}<label>音量<input type="range" name="volume" min="0" max="1" step="0.05" value="${v.volume}"></label><label>話す頻度<select name="frequency">${[['low','控えめ'],['normal','標準'],['high','多め']].map(([k,l])=>`<option value="${k}" ${v.frequency===k?'selected':''}>${l}</option>`).join('')}</select></label><div class="two"><label>静かな時間の開始（時）<input type="number" name="quietStart" min="0" max="23" required value="${v.quietStart}"></label><label>終了（時）<input type="number" name="quietEnd" min="0" max="23" required value="${v.quietEnd}"></label></div><button type="submit" class="primary wide">音声設定を保存</button></form><p class="muted">${E(host.voiceStatus?host.voiceStatus():'音声は未準備です。文字で利用できます。')}</p><p class="muted">音声搭載時のクレジット：<br>VOICEVOX:小夜/SAYO<br>VOICEVOX:ナースロボ＿タイプＴ<br>CORE 0.17.0 / VOICEVOX ONNX Runtime 1.23.2<br>音声ライブラリの利用条件は同梱のLICENSESをご確認ください。モデル未準備でも学習は利用できます。</p><button class="text-button" data-action="licenses">クレジット・利用条件</button></section>`}

function chat(){const messages=(S.messages??[]).slice(-chatLimit),name=m=>m.speaker==='NurseT'?'ナースロボ＿タイプＴ':'小夜 / SAYO';return '<section class="chat-screen"><header class="chat-title"><div class="companion-pair">'+avatar('SAYO',true)+avatar('NurseT',true)+'</div><div><h1>小夜とTちゃん</h1><span class="muted">昨日から続く、いつもの会話</span></div></header><div class="messages" role="log" aria-label="小夜とTちゃんとの会話">'+((S.messages?.length??0)>chatLimit?'<button data-action="olderMessages">以前の会話を見る</button>':'')+(messages.length?messages.map(m=>{if(m.speaker==='event'){const x=S.sessions.find(x=>x.sessionId===m.sessionId),material=entity(S,'materials',x?.relatedMaterialId),task=entity(S,'tasks',x?.relatedTaskId);return '<article class="study-event"><div class="study-event-label">📖 Study completed</div><strong>'+E(material?.title||x?.title)+'</strong>'+(task?'<p>'+E(task.title)+'</p>':'')+'<p>'+fmt(x?totals(x,now()).study:0)+(material?' · '+material.progress+' / '+material.target+' '+E(material.unit):'')+'</p><time>'+dateKey(m.at,S.settings.utcOffsetMinutes)+' '+timeOf(m.at)+'</time><button data-classify="'+E(m.sessionId)+'">学習内容を見る</button></article>'}if(m.speaker==='user')return '<article class="message outgoing"><div class="message-body"><div class="bubble">'+E(m.text)+'</div><time>'+dateKey(m.at,S.settings.utcOffsetMinutes)+' '+timeOf(m.at)+'</time></div></article>';return '<article class="message-row incoming">'+avatar(m.speaker)+'<div class="message incoming"><div class="message-body"><div class="message-speaker">'+name(m)+'</div><div class="bubble">'+E(m.text)+'</div><div class="message-meta"><time>'+dateKey(m.at,S.settings.utcOffsetMinutes)+' '+timeOf(m.at)+'</time><button class="voice-replay" aria-label="'+name(m)+'の声をもう一度" data-replay="'+E(m.id)+'">▶ 声</button></div>'+(m.target?'<div class="quick-actions"><button class="primary" data-study="'+E(m.target.kind)+'" data-id="'+E(m.target.id)+'">続きから始める</button><button data-open-board="materials">別のところ</button></div>':'')+'</div></div></article>'}).join(''):'<article class="message-row incoming">'+avatar('SAYO')+'<div class="message incoming"><div class="message-speaker">小夜 / SAYO</div><div class="bubble">ここで、少しずつ話していこう。今日はどんな一日だった？</div></div></article>')+typingHtml()+initiativeChips(S.initiative?.activeProposal,'active')+'<div id="messages-end"></div></div><form class="composer" data-form="conversation"><label class="sr-only" for="message-text">メッセージ</label><textarea id="message-text" name="text" rows="1" maxlength="300" placeholder="メッセージ" enterkeyhint="send" required></textarea>'+voiceToggle()+'<button type="submit" class="primary" aria-label="送信">送信</button></form></section>'}

function weeklyReview(){const w=weeklySummary(S.lifeBalanceAnalytics,weekStart(now())),insights=behaviorInsights(S.lifeBalanceAnalytics);return `<h1>今週の生活バランス</h1><section class="card"><p>記録あり ${w.observedDays} / 7日・終日確認済み ${w.completeDays}日</p><p>勉強 ${fmt(w.studyMinutes*60)}</p><p>娯楽 ${fmt(w.entertainmentMinutes*60)}</p><p>学習目標達成 ${w.studyGoalSuccessDays} / ${w.completeDays}日</p><p>娯楽予算内 ${w.budgetSuccessDays} / ${w.budgetEligibleDays}日</p><p>先週比 ${w.comparisonAvailable?E((w.studyDeltaMinutes>=0?'+':'')+w.studyDeltaMinutes+'分（学習） / '+(w.entertainmentDeltaMinutes>=0?'+':'')+w.entertainmentDeltaMinutes+'分（娯楽）'):'比較できる終日記録が不足しています'}</p><p class="muted">未取得の日は0分とみなしません。更新時点までの部分集計を含みます。</p><button data-action="refreshBalance">今日の集計を保存</button>${insights.map(i=>`<p>${E(i.text)}</p>`).join('')}</section><button data-page="chat">会話へ戻る</button>`}
